def f(n):
    def factorial(i):
        result = 1
        for j in range(2, i + 1):
            result *= j
        return result

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(i * (i + 1) // 2)
    return result
