def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    # Find the last consonant from the right side
    last_consonant = ""
    for char in reversed(word):
        if char.isalpha() and char not in vowels:
            last_consonant = char
            break
    else:
        last_consonant = word[-1] if word[-1].isalpha() else ""

    # Find all consonants from the right side
    consonants_from_right = []
    for i in range(len(word) - 1, -1, -1):
        char = word[i]
        if char.isalpha() and char not in vowels:
            consonants_from_right.append(char)

    # Find the closest vowel between two consonants from the right
    closest_vowel = ""
    for vowel_char in reversed(word):
        if vowel_char in vowels:
            # Check if it's between two consonants from the right
            found = False
            for j in range(len(consonants_from_right) - 1):
                if consonants_from_right[j] == word[j]:
                    found = True
                    break
            if found:
                closest_vowel = vowel_char
                break

    return closest_vowel if closest_vowel else ""
