def specialFilter(nums):
    count = 0
    for num in nums:
        if num <= 10:
            continue

        if num < 0:
            num = abs(num)
        else:
            num = num

        # Get first and last digits
        first_digit = num // 10
        last_digit = num % 10

        # Check if both are odd
        if first_digit % 2 == 1 and last_digit % 2 == 1:
            count += 1

    return count
