def largest_divisor(n: int) -> int:
    """For a given number n, find the largest number that divides n evenly, smaller than n"""
    if n <= 1:
        return 1
    smallest_divisor = 2
    while smallest_divisor * smallest_divisor <= n:
        if n % smallest_divisor == 0:
            return n // smallest_divisor
        smallest_divisor += 1
    return n
